"""Research bibliography, event archive and Cosmos series. Preserve existing bilingual pages."""
from pathlib import Path
import json,re,html,collections
ROOT=Path(__file__).resolve().parents[1];S=ROOT/'source';D=ROOT/'dist'
publications=json.loads((S/'publications.json').read_text());events=json.loads((S/'events.json').read_text());videos=json.loads((S/'cosmos.json').read_text())
def h(s):return html.escape(str(s),quote=True)
def link(url,label):return f'<a href="{h(url)}" target="_blank" rel="noopener">{h(label)}</a>'
def block(s,id,content):
 pattern=rf'<!-- {id}:start -->.*?<!-- {id}:end -->'
 s=re.sub(pattern,'',s,flags=re.S)
 return s, f'<!-- {id}:start -->{content}<!-- {id}:end -->'
for en in (False,True):
 root=D/'en' if en else D; asset='../assets/' if en else 'assets/'
 t=lambda es,eng:eng if en else es
 labels={'article':t('Artículo de revista','Journal article'),'proceedings':t('Memorias y capítulos','Proceedings and chapters'),'preprint':t('Prepublicación','Preprint'),'book':t('Libro','Book')}
 years=sorted({r['year'] for r in publications},reverse=True)
 pubrows=[]
 for year in years:
  cards=[]
  for r in publications:
   if r['year']!=year:continue
   citation=' · '.join(str(x) for x in [r['journal'],r.get('volume'),r.get('pages')] if x)
   shortauthors='; '.join(r['authors'][:8])+(' et al.' if len(r['authors'])>8 else '')
   authfull=('<p>'+h('; '.join(r['authors']))+'</p>') if len(r['authors'])>8 else ''
   aff='<ul>'+''.join('<li><strong>'+h(a['author'])+'</strong>: '+h(a['affiliation'])+'</li>' for a in { (a['author'],a['affiliation']):a for a in r['affiliations']}.values())+'</ul>'
   pre=link(r['preprintUrl'],t('Versión previa','Preprint version')) if r.get('preprintUrl') else ''
   cards.append(f'''<article class="publication" data-publication data-year="{year}" data-kind="{r['kind']}"><div class="pub-meta"><span>{labels[r['kind']]}</span><span>{year}</span></div><h3>{link(r['url'],r['title'])}</h3><p class="pub-authors">{h(shortauthors)}</p><p class="pub-journal">{h(citation)}</p><div class="pub-links">{link(r['url'],'DOI: '+r['doi'])}{pre}</div><details><summary>{t('Afiliación OAN y fuentes del registro','OAN affiliation and record sources')}</summary>{authfull}{aff}<p>{t('Afiliaciones registradas en OpenAlex; metadatos editoriales contrastados en Crossref cuando están disponibles.','Affiliations recorded in OpenAlex; publisher metadata cross-checked in Crossref when available.')}</p><p>{link(r['affiliationSource'],'OpenAlex')} · {link(r['metadataSource'],t('Metadatos bibliográficos','Bibliographic metadata'))}</p></details></article>''')
  pubrows.append(f'<div class="publication-year" data-publication-year="{year}"><h3 class="pub-year-heading">{year} <span>{len(cards)}</span></h3>{"".join(cards)}</div>')
 publicationsection=f'''<section id="publicaciones" class="research-catalog"><p class="eyebrow">{t('PRODUCCIÓN CIENTÍFICA','SCIENTIFIC PUBLICATIONS')}</p><h2>{t('Publicaciones por año','Publications by year')}</h2><p class="intro">{t('Investigación que lleva el nombre del Observatorio al mundo.','Research that carries the Observatory’s name into the world.')}</p><p>{t('Este catálogo reúne','This catalogue brings together')} <strong>{len(publications)}</strong> {t('registros de 1994 a 2026 con autores de la comunidad del OAN y al menos una afiliación explícita al Observatorio Astronómico Nacional de la Universidad Nacional de Colombia.','records from 1994 to 2026 featuring members of the OAN community and at least one explicit affiliation with the National Astronomical Observatory at Universidad Nacional de Colombia.')}</p><form class="catalog-controls" id="publication-form" role="search"><label>{t('Título, autor o tema','Title, author or topic')}<input id="publication-search" type="search" placeholder="{t('Busca en la bibliografía…','Search the bibliography…')}"></label><label>{t('Año','Year')}<select id="publication-year"><option value="all">{t('Todos','All')}</option>{''.join(f'<option>{y}</option>' for y in years)}</select></label><label>{t('Tipo','Type')}<select id="publication-kind"><option value="all">{t('Todos','All')}</option>{''.join(f'<option value="{k}">{v}</option>' for k,v in labels.items())}</select></label><button type="reset">{t('Limpiar','Reset')}</button></form><p id="publication-count" aria-live="polite">{len(publications)} {t('publicaciones','publications')}</p><p id="publication-empty" hidden>{t('No hay publicaciones que coincidan con los filtros.','No publications match these filters.')}</p><details class="catalog-method"><summary>{t('Criterio de inclusión y alcance','Inclusion criteria and coverage')}</summary><p>{t('No basta con encontrar un apellido o una afiliación genérica a la UNAL: el registro debe identificar expresamente al OAN y a la Universidad Nacional de Colombia. Se buscaron variantes de la afiliación en español e inglés y nombres de docentes y estudiantes. Cada ficha permite consultar la afiliación registrada y su fuente.','A matching surname or a general UNAL affiliation is not sufficient: the record must explicitly identify OAN and Universidad Nacional de Colombia. Searches used Spanish and English affiliation variants and faculty and student names. Each entry provides its recorded affiliation and source.')}</p><p>{t('Se contrastaron títulos, DOI, autores y años con metadatos editoriales disponibles en Crossref. Las afiliaciones proceden de los registros públicos de OpenAlex; no equivalen a una revisión manual de cada PDF. Las prepublicaciones están diferenciadas y no se presentan como artículos arbitrados. Cuando se identifica una versión editorial del mismo trabajo, se evita contar la prepublicación dos veces.','Titles, DOIs, authors and years were checked against publisher metadata available in Crossref. Affiliations come from public OpenAlex records; this is not a manual review of every PDF. Preprints are labelled separately and are not presented as peer-reviewed articles. When a matching publisher version is identified, the preprint is not counted twice.')}</p><p>{t('Es un catálogo documental en ampliación, no un inventario exhaustivo de toda la producción histórica. El año corresponde al registro de publicación, incluida la publicación anticipada cuando está disponible. Corte de búsqueda: 2 de octubre de 2026.','This is an expanding documentary catalogue, not an exhaustive inventory of all historical output. Years follow publication metadata, including online-first publication where available. Search cutoff: October 2, 2026.')}</p></details><div class="publication-list">{''.join(pubrows)}</div></section>'''
 p=root/'investigacion.html';s=p.read_text();s=re.sub(r'<section id="publicaciones".*?</section>',lambda _:publicationsection,s,flags=re.S)
 s=s.replace('<a href="#publicaciones">', '<a href="eventos.html">'+t('Eventos','Events')+'</a><a href="#publicaciones">') if 'href="eventos.html"' not in s.split('<main')[1].split('</main>')[0] else s
 p.write_text(s)
 # New event archive uses the established common header and footer.
 template=(root/'investigacion.html').read_text();title=t('Encuentros que conectan la astronomía','Meetings that connect astronomy')
 eventcards=[]
 for e in events:
  stat=t('Próximo','Upcoming') if e['status']=='upcoming' else t('Memoria','Archive')
  img=f'<a class="event-poster" href="{h(e["url"])}" target="_blank" rel="noopener"><img loading="lazy" src="{asset}{e["image"]}" alt="{h(t("Cartel oficial de ","Official poster for ")+e["title"])}"></a>' if e.get('image') else ''
  eventcards.append(f'''<article class="event-card {'has-poster' if img else ''}" id="{e['id']}">{img}<div class="event-copy"><div class="pub-meta"><span>{stat}</span><span>{e['date'][:4]}</span></div><h2>{h(e['title'])}</h2><p class="event-date">{h(e['date'])} · {h(e['place'])}</p><p class="event-role">{h(e['role'][1 if en else 0])}</p><p>{h(e['description_en' if en else 'description_es'])}</p>{link(e['url'],t('Sitio y documentación del evento','Event website and documentation'))}</div></article>''')
 main=f'''<main id="contenido"><div class="page-hero"><p class="eyebrow">{t('EVENTOS · OAN','EVENTS · OAN')}</p><h1>{title}</h1><p>{t('Congresos, escuelas y espacios de cooperación: una memoria de los encuentros impulsados por el Observatorio y sus alianzas.','Conferences, schools and collaborative spaces: a record of meetings supported by the Observatory and its partnerships.')}</p></div><div class="content"><p class="note">{t('Cada evento indica el papel documentado del OAN: organización, sede, comité o actividad relacionada. LARIM 2026 es organizado por instituciones mexicanas; el OAN participa en el comité científico de su taller satélite 4WAI. Las fechas pasadas se conservan como archivo, no como inscripciones abiertas.','Each event identifies OAN’s documented role: organizer, host, committee member or related activity. LARIM 2026 is organized by Mexican institutions; OAN participates on the scientific committee of its satellite workshop 4WAI. Past dates are retained as an archive, not as open registrations.')}</p><div class="event-list">{''.join(eventcards)}</div><p class="source-note">{t('Fechas en formato año-mes-día. Cuando solo se muestra un año, la ficha no asigna una fecha más precisa. Carteles: organizaciones CoCoA 2026 e IAUS400.','Dates use year-month-day format. Entries showing only a year do not assign a more precise date. Posters: CoCoA 2026 and IAUS400 organizers.')}</p></div></main>'''
 s=re.sub(r'<main\b.*?</main>',lambda _:main,template,flags=re.S);s=re.sub(r'<title>.*?</title>',f'<title>{title} · OAN</title>',s)
 # Only language/alternate links change route; navigation keeps Research.
 s=re.sub(r'(<a lang="(?:es|en)" href="[^"]*)investigacion.html',r'\1eventos.html',s)
 s=re.sub(r'(<link rel="alternate"[^>]*href="[^"]*)investigacion.html',r'\1eventos.html',s)
 (root/'eventos.html').write_text(s)
 # The playlists provide access to every episode; the card library presents verified selections.
 playlists=['PLWVo5HIkfQrZ10phybkn78E-5RulWtpv-','PLWVo5HIkfQrbjpwke1R5NMLkE4qWtUodt','PLWVo5HIkfQraXwwYRpkSlD7DGPj6i5S2c']
 seasons=[]
 for i,pid in enumerate(playlists,1):
  direct='https://www.youtube.com/playlist?list='+pid
  seasons.append(f'<article class="cosmos-season"><h3>{t("Temporada","Season")} {i}</h3><div class="cosmos-playlist" data-playlist="{pid}"><button type="button" class="load-playlist">{t("Reproducir la lista completa","Play the full playlist")}</button></div>{link(direct,t("Abrir temporada en YouTube","Open season on YouTube"))}</article>')
 cards=[]
 translations={'E0RQY5CgKuQ':'Episode 1','0b5fdrsLRjI':'Black holes','w4kbjDjGoQ0':'Moons in the Solar System','RKfTlwhcxYk':'Planetary nebulae','SNHsWHCziEw':'Space probes','UYX6BV9Fziw':'The invisible sky','5A7vSuuuZhc':'All about the Moon','tPv6uCFyNWs':'Binary systems','5DczpMykr00':'FITS Liberator launch','vg6b81GqEVw':'Worlds beyond our Solar System','4QeZPxZtvjc':'All about the solstice','_7Sbxea7aag':'Space rocks','x89BLXtWdYE':'As space tourists'}
 for v in videos:
  display=translations[v['id']] if en else re.sub(r'^.*?Programa\s*\d+\s*[:.\-]?\s*','',v['title']).strip() or 'Programa 1'
  cards.append(f'<article class="cosmos-video"><a href="{v["url"]}" target="_blank" rel="noopener"><img src="{asset}{v["image"]}" alt="{h(v["title"])}" loading="lazy"><span class="cosmos-video-copy"><small>{t("Temporada","Season")} {v["season"]} · {t("Programa","Episode")} {v["episode"]}</small><strong>{h(display)}</strong><span>{t("Ver en YouTube","Watch on YouTube")}</span></span></a></article>')
 cosmos=f'''<section id="navegando" class="cosmos-section"><p class="eyebrow">{t('SERIE AUDIOVISUAL','VIDEO SERIES')}</p><h2>Navegando por el Cosmos</h2><p class="intro">{t('Una conversación para viajar del cielo cercano a las grandes preguntas del universo.','A conversation that travels from our nearby sky to the universe’s biggest questions.')}</p><p>{t('La serie de divulgación del canal del Observatorio reúne conversaciones sobre astronomía y ciencias del espacio. Explora sus tres temporadas y una selección de episodios sobre agujeros negros, la Luna, estrellas, exploración y otros mundos.','The Observatory’s outreach series brings together conversations on astronomy and space science. Explore its three seasons and a selection of episodes on black holes, the Moon, stars, exploration and other worlds.')}</p><div class="cosmos-seasons">{''.join(seasons)}</div><h3>{t('Biblioteca de episodios · selección verificada','Episode library · verified selection')}</h3><p class="source-note">{t('13 episodios con títulos y miniaturas del canal oficial. Las listas superiores dan acceso al resto de la serie.','13 episodes with titles and thumbnails from the official channel. The playlists above provide access to the rest of the series.')}{t('',' Videos are in Spanish; English headings are navigation translations.')}</p><div class="cosmos-grid">{''.join(cards)}</div><p>{link('https://www.youtube.com/@astronomiaoan',t('Canal del Observatorio','Observatory channel'))}</p></section>'''
 p=root/'divulgacion.html';s=p.read_text();s,marked=block(s,'cosmos',cosmos);s=s.replace('<section id="canales">',marked+'<section id="canales">');s=s.replace('<a href="#canales">','<a href="#navegando">Navegando por el Cosmos</a><a href="#canales">') if 'href="#navegando"' not in s else s;p.write_text(s)
 # Featured events on the homepage, with a prominent archival poster and a clear upcoming event.
 featured=f'''<section class="section event-home"><div class="section-heading"><p class="eyebrow">{t('ENCUENTROS Y COMUNIDAD','MEETINGS AND COMMUNITY')}</p><h2>{t('La astronomía se construye juntos','Building astronomy together')}</h2><p>{t('Congresos, escuelas y cooperación internacional desde el Observatorio.','Conferences, schools and international cooperation through the Observatory.')}</p></div><div class="event-home-grid"><a class="event-home-poster" href="eventos.html#iaus400"><img src="{asset}iaus400-poster.jpg" alt="{t('Cartel oficial del IAU Symposium 400','Official IAU Symposium 400 poster')}" loading="lazy"></a><div><p class="eyebrow">{t('PRÓXIMO · 30 NOV – 1 DIC 2026','UPCOMING · NOV 30 – DEC 1, 2026')}</p><h3>4WAI · {t('Astronomía accesible e inclusiva','Accessible and inclusive astronomy')}</h3><p>{t('Cancún. Taller satélite de LARIM 2026 con participación del OAN en su comité científico.','Cancún. A LARIM 2026 satellite workshop with OAN participation on its scientific committee.')}</p><a class="button" href="eventos.html#wai2026">{t('Conocer el encuentro','Explore the workshop')}</a><hr><h3>CoCoA 2026 · Bogotá</h3><p>{t('Revive el IX Congreso Colombiano de Astronomía y Astrofísica y explora la memoria de nuestros eventos.','Revisit the IX Colombian Astronomy and Astrophysics Congress and explore the events archive.')}</p><a href="eventos.html">{t('Ver los 14 encuentros y ediciones','Explore 14 meetings and editions')}</a></div></div></section>'''
 p=root/'index.html';s=p.read_text();s,marked=block(s,'event-home',featured);s=s.replace('<section class="friends-banner">',marked+'<section class="friends-banner">');p.write_text(s)
 # Replace repeated campus photograph, while retaining it once on the home page.
 p=root/'profesores.html';s=p.read_text();s=re.sub(r'<figure class="editorial-image">(?:(?!</figure>).)*sede-academica.jpg.*?</figure>',f'<figure class="editorial-image"><img src="{asset}abell2744.jpg" alt="Abell 2744 · Hubble" loading="lazy"><figcaption>Abell 2744 · NASA, ESA, HFF Team, J. Lotz, M. Mountain, A. Koekemoer (STScI).</figcaption></figure>',s,flags=re.S);p.write_text(s)
 p=root/'egresados.html';s=p.read_text().replace('sede-academica.jpg','cosmic-cliffs.jpg').replace('Sede académica del Observatorio Astronómico Nacional','Nebulosa de Carina · Webb').replace('Academic building of the National Astronomical Observatory','Carina Nebula · Webb').replace('El Observatorio: punto de partida de nuevas preguntas.','Nebulosa de Carina · NASA, ESA, CSA, STScI.').replace('The Observatory: a starting point for new questions.','Carina Nebula · NASA, ESA, CSA, STScI.');p.write_text(s)
 # Shared navigation/assets for all pages.
 for p in root.glob('*.html'):
  s=p.read_text()
  if '<a href="eventos.html">' not in s.split('<main')[0]:s=s.replace('<a href="egresados.html">',f'<a href="eventos.html">{t("Eventos","Events")}</a><a href="egresados.html">',1)
  if 'research-update.css' not in s:s=s.replace('</head>',f'<link rel="stylesheet" href="{asset}research-update.css"><script defer src="{asset}research-update.js"></script></head>')
  p.write_text(s)
print('Updated research, events, outreach, imagery and navigation in ES/EN.')
# Image provenance and update documentation.
for en in (False,True):
 p=D/('en/fuentes.html' if en else 'fuentes.html');s=p.read_text()
 title='Research, events and new images' if en else 'Investigación, eventos y nuevas imágenes'
 credits=f'''<section><h2>{title}</h2><ul><li>Abell 2744: NASA, ESA, HFF Team, Jennifer Lotz, Matt Mountain, Anton Koekemoer (STScI). <a href="https://science.nasa.gov/asset/webb/hubble-frontier-field-abell-2744/">NASA</a>.</li><li>Carina: NASA, ESA, CSA, STScI. <a href="https://science.nasa.gov/asset/webb/cosmic-cliffs-in-the-carina-nebula-nircam-and-miri-composite-image/">NASA / Webb</a>.</li><li>IAUS 400: <a href="https://astronomiaoan.github.io/iaus400/index-es.html">Official event poster</a>. CoCoA 2026: <a href="https://accefyn.com/microsites/nodos/astroco/cocoa-2026/">AstroCO / ACCEFYN</a>.</li><li>Navegando por el Cosmos: <a href="https://www.youtube.com/@astronomiaoan">Observatorio Astronómico Nacional de Colombia</a>. Video thumbnails belong to their respective rights holders.</li><li>Bibliography: OpenAlex affiliation records and Crossref publisher metadata, consulted 2026-10-02. Original issue years are used for retrospective journal archives.</li></ul></section>'''
 s,marked=block(s,'research-credits',credits);p.write_text(s.replace('</main>',marked+'</main>'))
